create or replace function private.sales_charge_catalog_assert_v610(p_tenant_id uuid,p_service_variant_id uuid) returns void language plpgsql security definer set search_path=public,private,pg_temp as $$ begin if not exists(select 1 from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id where pv.id=p_service_variant_id and pv.tenant_id=p_tenant_id and pv.status='active' and p.status='active' and p.item_type='service') then raise exception 'Commercial charge must reference an active service product variant'; end if; end; $$;;
